-- Rollback: UPDATE papers SET body_md = (SELECT h.body_md FROM paper_version_history h WHERE h.slug = 'ignorance-ai-pipeline-synthesis' AND h.version = 'v0.2.1'), version = 'v0.2.1', updated_at = datetime('now'), change_actor = 'rem-a7-f4:uia-source-fidelity-100140:rollback-2', change_reason = 'rollback of the UIA-SOURCE-FIDELITY-1 judgement edits (items 2 and 4)' WHERE slug = 'ignorance-ai-pipeline-synthesis' AND version = 'v0.2.2' AND EXISTS (SELECT 1 FROM paper_version_history h WHERE h.slug = 'ignorance-ai-pipeline-synthesis' AND h.version = 'v0.2.1'); UPDATE papers SET body_md = (SELECT h.body_md FROM paper_version_history h WHERE h.slug = 'universal-ignorance-audit' AND h.version = 'v0.3.1'), version = 'v0.3.1', updated_at = datetime('now'), change_actor = 'rem-a7-f4:uia-source-fidelity-100140:rollback-2', change_reason = 'rollback of the UIA-SOURCE-FIDELITY-1 judgement edits (items 2 and 4)' WHERE slug = 'universal-ignorance-audit' AND version = 'v0.3.2' AND EXISTS (SELECT 1 FROM paper_version_history h WHERE h.slug = 'universal-ignorance-audit' AND h.version = 'v0.3.1')

UPDATE papers SET body_md = replace(replace(body_md, 'The human researcher then supplied twelve sharper questions that added entire missing dimensions: power analysis, the somatic/tacit dimension, the protected-ignorance probe, and the wobble.', 'The human researcher then supplied twelve sharper questions that sharpened four dimensions the first extraction had already named: power analysis, the somatic/tacit dimension, the protected-ignorance probe, and the wobble.'), 'the human contributed the dimensions the AI''s own frame omitted (power, body, taboo)', 'the human contributed sharper questions on power, body and taboo'),
       version = 'v0.2.2', updated_at = datetime('now'), change_actor = 'rem-a7-f4:uia-source-fidelity-100140', change_reason = 'UIA-SOURCE-FIDELITY-1 (agent_issues 100140 and 100576; owner directive 2026-10-26 ''this issue should be handled automatically'', rule c: narrowest statement, no contribution fact the papers do not already state), item 2. Section 2 contradicted itself on who contributed which dimension in three sentences: the AI''s first extraction already named wobble probing, power analysis, the somatic dimension and protected ignorance (second paragraph), the human''s twelve sharper questions ''added entire missing dimensions'' with the same four (third paragraph), and the co-production sentence said the AI''s frame ''omitted'' them (fourth paragraph). The record cannot say which came first, so the narrowest statement that these three sentences, the Author contributions section and the Use of artificial intelligence statement all support is used: the first extraction named the four dimensions, the human''s questions sharpened them, and the human contributed sharper questions on power, body and taboo. ''added entire missing dimensions'' and ''the dimensions the AI''s own frame omitted'' are removed; no contribution fact is added. The prior body is kept as snapshot v0.2.1 in paper_version_history.'
 WHERE slug = 'ignorance-ai-pipeline-synthesis' AND status = 'published' AND version = 'v0.2.1' AND (instr(body_md, 'The human researcher then supplied twelve sharper questions that added entire missing dimensions: power analysis, the somatic/tacit dimension, the protected-ignorance probe, and the wobble.') > 0 OR instr(body_md, 'the human contributed the dimensions the AI''s own frame omitted (power, body, taboo)') > 0);

