       version = 'v0.3.2', updated_at = datetime('now'), change_actor = 'rem-a7-f4:uia-source-fidelity-100140', change_reason = 'UIA-SOURCE-FIDELITY-1 (agent_issues 100140 and 100576; owner directive 2026-10-26, rule c), item 4, the part the papers'' own text supports: the sibling list in Section 4 omitted willful ignorance, which the synthesis lists among the siblings the meta-audit generated and which is a question of the final instrument (Phase 5); it is added in the synthesis'' order. The sentence ''several of which were incorporated into the final fifteen-question instrument'' stays at ''several'', the narrowest wording the record supports: which of the final fifteen came out of the meta-audit is a fact only the owner''s record can supply and is asked on the owner card uia-meta-audit-origin. The prior body is kept as snapshot v0.3.1 in paper_version_history.'
 WHERE slug = 'universal-ignorance-audit' AND status = 'published' AND version = 'v0.3.1' AND (instr(body_md, 'discernment between generative and harmful ignorance, the gift of not-knowing)') > 0);
